<?php
if (!defined('ABSPATH')) exit;
function cad_dashboard(){if(!is_user_logged_in())return '<p>Please <a href="'.esc_url(wp_login_url(get_permalink())).'">log in</a> to view your dashboard.</p>'; $uid=get_current_user_id();$q=new WP_Query(['post_type'=>'cad_transaction','posts_per_page'=>-1,'meta_key'=>'_cad_customer','meta_value'=>$uid]);ob_start();?><section class="cad-dashboard"><h2>Welcome, <?php echo esc_html(wp_get_current_user()->display_name);?></h2><p><a href="<?php echo esc_url(wp_logout_url(home_url('/')));?>">Log out</a></p><?php if(!$q->have_posts()):?><p>Your purchase history will appear here.</p><?php else:while($q->have_posts()):$q->the_post();$id=get_the_ID();$car=get_post_meta($id,'_cad_car',true);?><article class="cad-card"><h3><?php echo esc_html($car?get_the_title($car):get_the_title());?></h3><p>Purchase date: <?php echo esc_html(get_the_date('', $id));?> · Amount: <?php echo esc_html(get_post_meta($id,'_cad_amount',true));?></p><?php foreach(['invoice'=>'Invoice','warranty'=>'Warranty document'] as $key=>$label){$url=get_post_meta($id,'_cad_'.$key,true);if($url)echo '<a class="button" target="_blank" rel="noopener" href="'.esc_url($url).'">'.esc_html($label).'</a> ';}?></article><?php endwhile;wp_reset_postdata();endif;?></section><?php return ob_get_clean();}
add_shortcode('cad_dashboard','cad_dashboard');
function cad_login(){if(is_user_logged_in())return '<p>You are logged in. <a href="'.esc_url(home_url('/dashboard/')).'">Go to dashboard</a>.</p>';return wp_login_form(['echo'=>false,'redirect'=>home_url('/dashboard/')]);}add_shortcode('cad_login','cad_login');
